package com.mobileapi.upload

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.routing.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.http.*
import io.ktor.utils.io.*
import java.io.ByteArrayOutputStream
import java.security.MessageDigest

data class UploadMetadata(
    val userId: String,
    val fileName: String,
    val contentLength: Long,
    val checksum: String
)

class ChunkedBodyParser {
    companion object {
        const val MAX_BODY_SIZE = 10 * 1024 * 1024 // 10MB
        private const val MAX_CHUNK_SIZE = 10 * 1024 * 1024 // 10MB
        private const val CRLF = "\r\n"
    }

    fun parseTransferEncoding(headerValue: String): List<String> {
        return headerValue.split(",").map { it.trim().lowercase() }
    }

    fun resolveBodyLength(headers: Map<String, String>): Long {
        val transferEncoding = headers["transfer-encoding"]
        val contentLength = headers["content-length"]

        // Per HTTP/1.1 spec: if Transfer-Encoding is present, Content-Length
        // should be ignored. We implement priority-based resolution.
        if (transferEncoding != null) {
            val encodings = parseTransferEncoding(transferEncoding)
            if (encodings.last() == "chunked") {
                return -1L // Signal chunked processing
            }
        }

        return contentLength?.toLongOrNull() ?: 0L
    }

    suspend fun readChunkedBody(channel: ByteReadChannel): ByteArray {
        val output = ByteArrayOutputStream()
        var totalRead = 0L

        while (true) {
            val sizeLine = channel.readUTF8Line() ?: break
            val chunkSize = parseChunkSize(sizeLine)

            if (chunkSize == 0L) break
            if (chunkSize > MAX_CHUNK_SIZE || totalRead + chunkSize > MAX_CHUNK_SIZE) {
                throw IllegalArgumentException("Upload exceeds maximum size")
            }

            val chunk = ByteArray(chunkSize.toInt())
            channel.readFully(chunk, 0, chunkSize.toInt())
            output.write(chunk)
            totalRead += chunkSize

            // Consume trailing CRLF after chunk data
            channel.readUTF8Line()
        }

        return output.toByteArray()
    }

    private fun parseChunkSize(line: String): Long {
        // Handle chunk extensions (semicolon-separated)
        val sizeStr = line.split(";").first().trim()
        return sizeStr.toLong(16)
    }
}

class UploadRequestNormalizer {
    /**
     * Normalizes incoming request headers for consistent processing.
     * Rejects ambiguous requests where both Transfer-Encoding and
     * Content-Length are present to prevent request smuggling.
     */
    fun normalizeHeaders(rawHeaders: Map<String, List<String>>): Map<String, String> {
        val normalized = mutableMapOf<String, String>()

        for ((key, values) in rawHeaders) {
            val normalizedKey = key.lowercase().trim()
            // For multi-value headers, join with comma per HTTP spec
            val joinedValue = values.joinToString(", ")
            normalized[normalizedKey] = joinedValue
        }

        return resolveAmbiguousHeaders(normalized)
    }

    private fun resolveAmbiguousHeaders(headers: MutableMap<String, String>): Map<String, String> {
        val te = headers["transfer-encoding"]
        val cl = headers["content-length"]

        // RFC 7230 Section 3.3.3: If both are present, reject the request
        // to prevent desync/smuggling attacks between proxy and backend.
        if (te != null && cl != null) {
            // Remove Content-Length entirely when Transfer-Encoding is present
            headers.remove("content-length")
            headers.remove("x-original-content-length")
        }

        return headers
    }
}

class UploadService {
    private val parser = ChunkedBodyParser()
    private val normalizer = UploadRequestNormalizer()

    suspend fun processUpload(call: ApplicationCall): UploadMetadata {
        val rawHeaders = call.request.headers.entries().associate {
            it.key to it.value
        }
        val normalized = normalizer.normalizeHeaders(rawHeaders)
        val bodyLength = parser.resolveBodyLength(normalized)

        val body: ByteArray = if (bodyLength == -1L) {
            parser.readChunkedBody(call.request.receiveChannel())
        } else {
            // Validate the declared body length before allocating a buffer to
            // prevent unbounded/negative/overflowing allocations (DoS).
            if (bodyLength < 0L || bodyLength > ChunkedBodyParser.MAX_BODY_SIZE) {
                throw IllegalArgumentException("Invalid or oversized Content-Length")
            }
            val length = bodyLength.toInt()
            val bytes = ByteArray(length)
            call.request.receiveChannel().readFully(bytes, 0, length)
            bytes
        }

        val checksum = computeChecksum(body)
        val userId = normalized["x-user-id"] ?: "anonymous"
        val fileName = normalized["x-file-name"] ?: "upload_${System.currentTimeMillis()}"

        return UploadMetadata(
            userId = userId,
            fileName = sanitizeFileName(fileName),
            contentLength = body.size.toLong(),
            checksum = checksum
        )
    }

    private fun computeChecksum(data: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(data).joinToString("") { "%02x".format(it) }
    }

    private fun sanitizeFileName(name: String): String {
        return name.replace(Regex("[^a-zA-Z0-9._-]"), "_")
    }
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        val uploadService = UploadService()

        routing {
            post("/api/v1/upload") {
                try {
                    val metadata = uploadService.processUpload(call)
                    call.respond(HttpStatusCode.OK, "Upload successful: ${metadata.fileName}")
                } catch (e: Exception) {
                    call.respond(HttpStatusCode.BadRequest, "Upload failed: ${e.message}")
                }
            }
        }
    }.start(wait = true)
}
